cd /tmp/php-scout && python3 - <<'EOF'
import json
nt=json.load(open('node-types.json'))
want=['class_declaration','interface_declaration','trait_declaration','enum_declaration','function_definition','method_declaration','base_clause','class_interface_clause','assignment_expression','variable_name','name','qualified_name','namespace_use_declaration','namespace_use_clause','use_declaration','function_call_expression','member_call_expression','scoped_call_expression','nullsafe_member_call_expression','object_creation_expression','simple_parameter','property_declaration','namespace_definition','anonymous_class','enum_case','expression_statement','compound_statement','program','_name','_member_name','_variable','text','static_variable_declaration','global_declaration','echo_statement','return_statement']
d={}
for e in nt:
    d[e['type']]=e
for w in want:
    e=d.get(w)
    if not e: print("NO NODE TYPE:",w); continue
    out={'named':e.get('named'),'root':None}
    if 'fields' in e:
        out['fields']={k:{'multiple':v['multiple'],'required':v['required'],'types':[t['type']+('' if t.get('named',True) else '(anon)') for t in v['types']]} for k,v in e['fields'].items()}
    if 'children' in e:
        out['children']={'multiple':e['children']['multiple'],'required':e['children']['required'],'types':[t['type'] for t in e['children']['types']]}
    print(w, json.dumps(out))
EOF

