            bases
        );
        assert!(
            bases.iter().any(|b| b.contains("ICanRun")),
            "expected implements ICanRun, got {:?}",
            bases
        );
        assert!(
            bases.iter().any(|b| b.contains("ICanSwim")),
            "expected implements ICanSwim, got {:?}",
            bases
        );
    }

